<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
class ApiController extends Controller {
 private function page(Request $r,array $data){$p=max(1,(int)$r->query('page',1));$n=max(1,min(100,(int)$r->query('per_page',10)));return response()->json(['data'=>array_slice($data,($p-1)*$n,$n),'meta'=>['page'=>$p,'per_page'=>$n,'total'=>count($data)]]);}
 public function createReservation(Request $r){$v=$r->validate(['customer.name'=>'required','customer.document'=>'required','pickup_agency_id'=>'required','return_agency_id'=>'required','pickup_at'=>'required|date','return_at'=>'required|date|after:pickup_at','vehicle_category'=>'required','insurances'=>'array']);return response()->json(['id'=>'RSV-'.random_int(10000,99999),'status'=>'confirmed','total'=>684.90,'currency'=>'BRL','request'=>$v],201);}
 public function vehicles(Request $r){return $this->page($r,[['id'=>'VH-1001','model'=>'Chevrolet Onix','category'=>'Hatch','daily_price'=>139.90,'transmission'=>'automatic','fuel'=>'flex'],['id'=>'VH-1002','model'=>'Jeep Renegade','category'=>'SUV','daily_price'=>239.90,'transmission'=>'automatic','fuel'=>'flex'],['id'=>'VH-1003','model'=>'BYD Dolphin','category'=>'Electric','daily_price'=>269.90,'transmission'=>'automatic','fuel'=>'electric']]);}
 public function coupon(Request $r){$v=$r->validate(['reservation_id'=>'required','coupon'=>'required']);return response()->json(['reservation_id'=>$v['reservation_id'],'coupon'=>$v['coupon'],'discount_percent'=>10,'status'=>'applied']);}
 public function telemetry($id){return response()->json(['vehicle_id'=>$id,'gps'=>['lat'=>-19.9191,'lng'=>-43.9386],'odometer_km'=>42871,'fuel_percent'=>67,'speed_kmh'=>42,'status'=>'moving','recorded_at'=>now()]);}
 public function driver(Request $r,$id){$v=$r->validate(['driver_id'=>'required']);return response()->json(['vehicle_id'=>$id,'driver_id'=>$v['driver_id'],'status'=>'linked']);}
 public function geofence(Request $r,$id){$v=$r->validate(['name'=>'required','center.lat'=>'required|numeric','center.lng'=>'required|numeric','radius_m'=>'required|integer|min:50']);return response()->json(['id'=>'GEO-'.random_int(1000,9999),'vehicle_id'=>$id]+$v,201);}
 public function claim(Request $r){$v=$r->validate(['vehicle_id'=>'required','driver_id'=>'required','description'=>'required','photos'=>'array','police_report_url'=>'nullable|url']);return response()->json(['id'=>'CLM-'.random_int(1000,9999),'status'=>'opened','request'=>$v],201);}
 public function maintenance(Request $r){$v=$r->validate(['vehicle_id'=>'required','scheduled_at'=>'required|date','service_type'=>'required']);return response()->json(['id'=>'MNT-'.random_int(1000,9999),'status'=>'scheduled','request'=>$v],201);}
 public function history(Request $r,$id){return $this->page($r,[['vehicle_id'=>$id,'date'=>'2026-08-10','service'=>'oil_and_filters','odometer_km'=>40000,'dashboard_alerts'=>[]],['vehicle_id'=>$id,'date'=>'2026-05-02','service'=>'brakes','odometer_km'=>35000,'dashboard_alerts'=>['tire_pressure']]]);}
 public function billing(Request $r){return $this->page($r,[['invoice_id'=>'INV-901','customer_id'=>$r->query('customer_id','C-001'),'amount'=>1840.50,'status'=>'paid','due_date'=>'2026-10-10'],['invoice_id'=>'INV-902','customer_id'=>$r->query('customer_id','C-001'),'amount'=>720.00,'status'=>'open','due_date'=>'2026-11-10']]);}
 public function fines(Request $r){return $this->page($r,[['id'=>'FINE-101','vehicle_id'=>$r->query('vehicle_id','VH-1001'),'driver_id'=>$r->query('driver_id','DRV-77'),'amount'=>195.23,'status'=>'pending','occurred_at'=>'2026-09-21']]);}
}